-- Seed idempotente: 100 autores e 100 livros para desenvolvimento.
-- IDs fixos permitem relacionar cada livro ao seu autor no banco.




SELECT setval(pg_get_serial_sequence('autores', 'id'), GREATEST(COALESCE((SELECT MAX(id) FROM autores), 1), 1), true);
SELECT setval(pg_get_serial_sequence('livros', 'id'), GREATEST(COALESCE((SELECT MAX(id) FROM livros), 1), 1), true);

-- Conta administrativa de desenvolvimento. A senha está armazenada em BCrypt.
WITH usuario_admin AS (
  VALUES (1000, 'admin', '$2a$10$I3hDZ4RcPu6lKZj/e2pGJOuaaYQyywGtx7IdcC3aLRkFKqIJ5wle6', 'admin@gmail.com', true)
  ON CONFLICT (user_id) DO UPDATE SET
    user_name = EXCLUDED.user_name,
    user_passwd = EXCLUDED.user_passwd,
    user_email = EXCLUDED.user_email,
    approved = EXCLUDED.approved
  RETURNING user_id
)
SELECT user_id, 'ADMIN' FROM usuario_admin
ON CONFLICT DO NOTHING;

SELECT setval('sq_user', GREATEST(COALESCE((SELECT MAX(user_id) FROM users), 1000), 1000), true);
